import json,os,shutil,stat
from pathlib import Path
folder=Path('/home/ubuntu/.cache/rea/hopper-releases')
expected='b2271008fb82bf14cfae5c3644cdde2b11fc6804bd7c99d67032ec1b1942d53c'
o={'action':'remove_obsolete_home_hopper_cache_only','removed':False}
try:
 assert str(folder.parent)=='/home/ubuntu/.cache/rea' and not folder.is_symlink()
 if not folder.exists():
  o['status']='already_absent'
 else:
  assert folder.is_dir() and folder.stat().st_uid==os.geteuid()
  items=sorted(x.name for x in folder.iterdir())
  assert items==[expected],'cache has unexpected contents; not removing'
  for process in Path('/proc').iterdir():
   if not process.name.isdigit():continue
   for item in ('cwd','exe'):
    try:
     target=os.readlink(process/item)
     if target.startswith(str(folder)+'/'):raise RuntimeError('cache in use by process '+process.name)
    except OSError:pass
   fd=process/'fd'
   try:
    for entry in fd.iterdir():
     try:
      target=os.readlink(entry)
      if target.startswith(str(folder)+'/'):raise RuntimeError('cache open by process '+process.name)
     except OSError:pass
   except OSError:pass
  size=sum(x.stat().st_size for x in folder.rglob('*') if x.is_file() and not x.is_symlink())
  shutil.rmtree(folder)
  o.update({'status':'removed','removed':True,'bytes_of_regular_files':size,'now_absent':not folder.exists()})
  parent=folder.parent
  if parent.is_dir() and not any(parent.iterdir()):
   parent.rmdir()
   o['empty_home_rea_cache_removed']=True
except Exception as e:
 o.update({'status':'not_removed','error':type(e).__name__+': '+str(e)[:150]})
print(json.dumps(o,separators=(',',':')))
